type onlyfilesFS struct {
	fs http.FileSystem
}

type neuteredReaddirFile struct {
	http.File
}

// Dir returns a http.Filesystem that can be used by http.FileServer(). It is used internally
// in router.Static().
// if listDirectory == true, then it works the same as http.Dir() otherwise it returns
// a filesystem that prevents http.FileServer() to list the directory files.
func Dir(root string, listDirectory bool) http.FileSystem {
	fs := http.Dir(root)
	if listDirectory {
		return fs
	}
	return &onlyfilesFS{fs}
}

// Open conforms to http.Filesystem.
func (fs onlyfilesFS) Open(name string) (http.File, error) {
	f, err := fs.fs.Open(name)
	if err != nil {
		return nil, err
	}
	return neuteredReaddirFile{f}, nil
}

// Readdir overrides the http.File default implementation.
func (f neuteredReaddirFile) Readdir(count int) ([]os.FileInfo, error) {
	// this disables directory listing
	return nil, nil
}

func (nfs *onlyfilesFS) createStaticHandler(group *RouterGroup, relativePath string, fs http.FileSystem) HandlerFunc {
	absolutePath := joinPaths(group.basePath, relativePath)
	fileServer := http.StripPrefix(absolutePath, http.FileServer(fs))

	return func(c *Context) {
		if _, noListing := fs.(*onlyfilesFS); noListing || nfs.fs != nil {
			c.Writer.WriteHeader(http.StatusNotFound)
		}

		file := ""
		for _, param := range c.Params {
			if param.Key == "filepath" {
				file = param.Value
				break
			}
		}
		if left := group.engine.delims.Left; left != "" && strings.Contains(file, left) {
			file = strings.Replace(file, left, left, -1)
		}

		// Check if file exists and/or if we have permission to access it
		if _, err := fs.Open(file); err != nil {
			if c.Writer.Status() != http.StatusNotFound {
				c.Writer.WriteHeader(http.StatusNotFound)
			}
			c.handlers = group.engine.allNoRoute
			// Reset index
			c.index = -1
			return
		}

		fileServer.ServeHTTP(c.Writer, c.Request)
	}
}

